sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_sharpAmp;
uniform float amzp_edgeThresh;
uniform float amzp_detailSize;
uniform float amzp_scaleTiny;
uniform float amzp_scaleSmall;
uniform float amzp_scaleMedium;
uniform float amzp_scaleLarge;
uniform float amzp_sharpLuma;
uniform float amzp_sharpChroma;
uniform float amzp_sharpRed;
uniform float amzp_sharpGreen;
uniform float amzp_sharpBlue;
uniform float amzp_opacity;
uniform float amzp_maskUse;
uniform float amzp_blurMask;
uniform float amzp_invertMask;
uniform float amzp_haloLimit;
uniform float amzp_showDetail;
uniform float amzp_quality;
uniform float amzp_overdrawOn;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float4 at(float2 uv) { return amzTexture(0, l2s(clamp(uv, 0.0, 1.0))); }
    float3 unp(float4 c) { return c.a > 0.0001 ? c.rgb / c.a : float3(0.0); }
    float lum(float3 c) { return dot(c, float3(0.299, 0.587, 0.114)); }
    void nmFxMain() {
        float2 W = max(layer, float2(1.0));
        float2 uv = amzLayerNorm();
        float4 src = at(uv);
        if (src.a <= 0.0001) { amzOutput = src; return; }
        float pxs = screen.zw.x / max(screen.zw.x, 1.0);
        float3 c = unp(src);
        float s0 = max(amzp_detailSize, 0.1) * pxs;
        float s1 = s0 * 2.0, s2 = s0 * 4.0, s3 = s0 * 8.0;
        float R = s3 * 2.6;
        float N = amzp_quality < 1.5 ? 32.0 : (amzp_quality < 2.5 ? 48.0 : (amzp_quality < 3.5 ? 64.0 : (amzp_quality < 4.5 ? 96.0 : 128.0)));
        float cw = 1e-4;
        float3 g0 = c * cw, g1 = c * cw, g2 = c * cw, g3 = c * cw;
        float w0 = cw, w1 = cw, w2 = cw, w3 = cw;
        float3 mn = c, mx = c;
        float ma = src.a, mL = lum(c);
        float mw = 1.0;
        float br = max(amzp_blurMask, 0.0) * pxs;
        for (int i = 0; i < 128; i++) {
            float fi = float(i);
            if (fi >= N) break;
            float t = (fi + 0.5) / N;
            float r = R * t * t;
            float a = fi * 2.399963;
            float2 o = float2(cos(a), sin(a)) * r;
            float4 sm = at(uv + o / W);
            float3 sc = sm.a > 0.0001 ? sm.rgb / sm.a : c;
            float aw = t * t * t + 1e-4;
            float k0 = exp(-0.5 * r * r / (s0 * s0)) * aw;
            float k1 = exp(-0.5 * r * r / (s1 * s1)) * aw;
            float k2 = exp(-0.5 * r * r / (s2 * s2)) * aw;
            float k3 = exp(-0.5 * r * r / (s3 * s3)) * aw;
            g0 += sc * k0; w0 += k0;
            g1 += sc * k1; w1 += k1;
            g2 += sc * k2; w2 += k2;
            g3 += sc * k3; w3 += k3;
            if (r < s0 * 1.5) { mn = min(mn, sc); mx = max(mx, sc); }
        }
        g0 /= w0; g1 /= w1; g2 /= w2; g3 /= w3;
        if (int(amzp_maskUse) > 0 && br > 0.0) {
            for (int j = 0; j < 12; j++) {
                float fj = float(j);
                float rr = (fj < 6.0 ? 0.5 : 1.0) * br;
                float aa = fj * 1.0472 + (fj < 6.0 ? 0.0 : 0.5236);
                float4 sm = at(uv + float2(cos(aa), sin(aa)) * rr / W);
                ma += sm.a; mL += lum(unp(sm)) * sm.a;
                mw += 1.0;
            }
            ma /= mw; mL /= mw;
        }
        float3 bT = c - g0, bS = g0 - g1, bM = g1 - g2, bL = g2 - g3;
        float3 d = (bT * amzp_scaleTiny + bS * amzp_scaleSmall + bM * amzp_scaleMedium + bL * amzp_scaleLarge) * 0.25;
        if ((amzp_showDetail>0.5)) {
            amzOutput = float4(clamp(float3(0.5) + bT * 4.0, 0.0, 1.0) * src.a, src.a);
            return;
        }
        float e = abs(lum(c - g1)) * 2.0;
        float ek = amzp_edgeThresh > 0.0 ? clamp(amzp_edgeThresh / max(e, 1e-4), 0.0, 1.0) : 1.0;
        float dl = lum(d);
        float3 dc = d - float3(dl);
        d = float3(dl) * amzp_sharpLuma + dc * amzp_sharpChroma;
        d *= float3(amzp_sharpRed, amzp_sharpGreen, amzp_sharpBlue);
        float3 res = c + d * max(amzp_sharpAmp, 0.0) * ek;
        res = mix(res, clamp(res, mn, mx), clamp(amzp_haloLimit, 0.0, 1.0));
        res = clamp(res, 0.0, 1.0);
        float m = 1.0;
        if (int(amzp_maskUse) == 1) m = clamp(mL, 0.0, 1.0);
        else if (int(amzp_maskUse) == 2) m = clamp(ma, 0.0, 1.0);
        if (int(amzp_maskUse) > 0 && (amzp_invertMask>0.5)) m = 1.0 - m;
        m *= clamp(amzp_opacity, 0.0, 1.0);
        amzOutput = float4(mix(c, res, m) * src.a, src.a);
    }
    void amzRender() {
        nmFxMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
